      "translations": {
        "en": "And by Your Name through which You raised the sky and built it"
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَبِاسْمِكَ الَّذِي خَلَقْتَ بِهِ الْخَلْقَ",
